from collections import Counter
import re

def count_top_words(file_path, top_n=3):
    """Counts the occurrences of words in a file and returns the top n words."""
    with open(file_path, 'r') as f:
        text = f.read().lower()

    # Use regex to find words (alphanumeric characters)
    words = re.findall(r'\w+', text)

    if not words:
        return []

    counts = Counter(words)
    return counts.most_common(top_n)

def main():
    file_path = 'file_1'
    try:
        top_words = count_top_words(file_path)
        if not top_words:
            print("No words found in the file.")
        else:
            print("The three most common words are:")
            for word, count in top_words:
                print(f"{word}: {count}")
    except FileNotFoundError:
        print(f"Error: {file_path} not found.")

if __name__ == "__main__":
    main()

