import os
import pandas as pd

def find_csv_files(start_dir='.'):
    csv_files = []
    for root, dirs, files in os.walk(start_dir):
        for file in files:
            if file.endswith('.csv'):
                csv_files.append(os.path.join(root, file))
    return csv_files

print("CSV files found:", find_csv_files())

def count_primes(n):
    """Counts the number of prime numbers less than n."""
    if n <= 2:
        return 0

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for p in range(2, int(n**0.5) + 1):
        if sieve[p]:
            for i in range(p * p, n, p):
                sieve[i] = False

    return sum(sieve)

def main():
    limit = 10000
    result = count_primes(limit)

    # Test with a known value: primes below 10 are 2, 3, 5, 7 (count = 4)
    assert count_primes(10) == 4, f"Expected 4, got {count_primes(10)}"
    # Test with another known value: primes below 20 are 2, 3, 5, 7, 11, 13, 17, 19 (count = 8)
    assert count_primes(20) == 8, f"Expected 8, got {count_primes(20)}"

    print(f"The number of prime numbers below {limit} is: {result}")

if __name__ == "__main__":
    main()
